import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
const report=readFileSync('docs/reviews/admission-acquisition-independent-review.txt','utf8');
const pin='5026604d3ef695651c21b24bd78410c7fec04b58';
const axiomPaths={A3:'axioms/A3-sovereign-composition.md',A4:'axioms/A4-zero-loss-knowledge.md',A8:'axioms/A8-gated-recursive-integrity.md',A9:'axioms/A9-chaos-validated-deployment.md',A14:'axioms/A14-compounding-learning.md'};
const checked=[];
for(const [,expected,reference] of report.matchAll(/^([0-9a-f]{64})  (.+)$/gmu)) {
 const data=axiomPaths[reference]?
  execFileSync('git',['-C','/home/apnex/taceng/mission-kit','show',pin+':'+axiomPaths[reference]]):
  readFileSync(reference);
 const actual=createHash('sha256').update(data).digest('hex');
 assert.equal(actual,expected,reference);
 checked.push({reference,bytes:data.length,sha256:actual});
}
assert.equal(checked.length,25);
let sourceCitations=0;
for(const [,file,line] of report.matchAll(/\]\((\/[^)]+):(\d+)\)/gu)) {
 const lines=readFileSync(file,'utf8').trimEnd().split('\n');
 assert.ok(Number(line)>=1 && Number(line)<=lines.length,file+':'+line);
 sourceCitations++;
}
assert.ok(sourceCitations>0);
console.log(JSON.stringify({status:'PASS',checked,sourceCitations,scope:'Source manifest equality and citation file/line existence; not semantic verification or runtime proof.'},null,2));
NODE

